<script setup>
import { onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { Plus, Send, RefreshCw } from 'lucide-vue-next'
import { api, getAll } from '../api'
import { CdcMessage, CdcMessageBox } from './ui/feedback'
const props=defineProps({history:Boolean,taskId:Number,hideRefresh:Boolean})
const rules=ref([]),tasks=ref([]),logs=ref([]),total=ref(0),page=ref(1),dialog=ref(false),busy=ref(false),recipients=ref('')
const labels={TASK_FAILURE:'任务失败',TABLE_FAILURE:'表同步失败',DDL_CHANGE:'表结构变化',CHECKPOINT_EXPIRED:'位点失效',DATA_DELAY:'数据延迟',RECONCILIATION_MISMATCH:'数据核对不一致'}
const frequencies={immediate:'立即发送','5min':'5 分钟聚合',hourly:'每小时汇总'}
const statuses={PENDING:'待发送',SENT:'已发送',FAILED:'发送失败',CANCELLED:'已取消'}
const form=reactive({})
let timer
onMounted(()=>{load();timer=setInterval(load,15000)})
onBeforeUnmount(()=>clearInterval(timer))
async function load(){try{if(props.history){const result=await api(`/mail/history?page=${page.value-1}&size=20`);logs.value=result.items.map(row=>Object.fromEntries(Object.entries(row).map(([k,v])=>[k.toLowerCase(),v])));total.value=result.total}else{rules.value=await api('/mail/rules');tasks.value=await getAll('/tasks')}}catch(e){CdcMessage.error(e.message)}}
function edit(rule){Object.assign(form,rule?JSON.parse(JSON.stringify(rule)):{id:null,name:'',description:'',enabled:true,recipients:[],alertTypes:['TASK_FAILURE','TABLE_FAILURE'],scope:props.taskId?'tasks':'all',taskIds:props.taskId?[props.taskId]:[],frequency:'immediate'});recipients.value=form.recipients.join(', ');dialog.value=true}
async function save(){busy.value=true;try{form.recipients=recipients.value.split(/[,;\s，；]+/).filter(Boolean);await api('/mail/rules'+(form.id?'/'+form.id:''),{method:form.id?'PUT':'POST',body:JSON.stringify(form)});dialog.value=false;CdcMessage.success('订阅规则已保存');await load()}catch(e){CdcMessage.error(e.message)}finally{busy.value=false}}
async function remove(rule){try{await CdcMessageBox.confirm('删除后停止此规则的待发送邮件，历史记录保留。','删除订阅规则');await api('/mail/rules/'+rule.id,{method:'DELETE'});await load()}catch(e){if(e!=='cancel')CdcMessage.error(e.message)}}
async function test(rule){try{await api(`/mail/rules/${rule.id}/test`,{method:'POST'});CdcMessage.success('测试邮件已加入队列，请查看邮件历史')}catch(e){CdcMessage.error(e.message)}}
async function retry(row){try{await api(`/mail/history/${row.id}/retry`,{method:'POST'});await load()}catch(e){CdcMessage.error(e.message)}}
const date=value=>value?new Date(value).toLocaleString():'—'
defineExpose({load})
</script>
<template>
  <div><div class="tab-toolbar"><p class="muted">{{history?'查看实际发送结果与失败记录':'订阅规则定义什么告警、发给谁、以什么频率。'}}</p><div class="mail-actions"><cdc-button v-if="!hideRefresh" @click="load"><RefreshCw :size="14"/>刷新</cdc-button><cdc-button v-if="!history" type="primary" @click="edit()"><Plus :size="14"/>新建订阅规则</cdc-button></div></div>
    <div v-if="!history" class="table-wrap"><table><thead><tr><th>规则</th><th>收件人</th><th>告警类型</th><th>关联任务</th><th>频率</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="rule in rules.filter(r=>!taskId||r.scope==='all'||r.taskIds.includes(taskId))" :key="rule.id"><td><strong>{{rule.name}}</strong><div class="muted">{{rule.description}}</div></td><td><span v-for="email in rule.recipients" :key="email" class="email-tag">{{email}}</span></td><td>{{rule.alertTypes.map(type=>labels[type]).join('、')}}</td><td>{{rule.scope==='all'?'全部任务':rule.taskIds.map(id=>tasks.find(t=>t.id===id)?.name||'#'+id).join('、')}}</td><td>{{frequencies[rule.frequency]}}</td><td><cdc-tag :type="rule.enabled?'success':'info'">{{rule.enabled?'已启用':'已停用'}}</cdc-tag></td><td><div class="row-actions"><cdc-button size="small" @click="edit(rule)">编辑</cdc-button><cdc-menu><button @click="test(rule)">发送测试邮件</button><button class="danger" @click="remove(rule)">删除</button></cdc-menu></div></td></tr></tbody></table><cdc-empty v-if="!rules.length" description="尚未配置邮件订阅"/></div>
    <template v-else><cdc-table :data="logs"><cdc-table-column label="时间" min-width="180"><template #default="{row}">{{date(row.sent_at||row.created_at)}}</template></cdc-table-column><cdc-table-column prop="recipient" label="收件人" min-width="190"/><cdc-table-column prop="subject" label="主题" min-width="260"/><cdc-table-column label="状态" width="110"><template #default="{row}"><cdc-tag :type="row.status==='SENT'?'success':row.status==='FAILED'?'danger':'info'">{{statuses[row.status]}}</cdc-tag></template></cdc-table-column><cdc-table-column prop="last_error" label="错误" min-width="250"/><cdc-table-column label="操作" width="90"><template #default="{row}"><cdc-button v-if="row.status==='FAILED'" size="small" @click="retry(row)">重试</cdc-button></template></cdc-table-column></cdc-table><cdc-pagination v-model:current-page="page" :total="total" :page-size="20" @current-change="load"/></template>
    <cdc-modal v-model="dialog" :title="form.id?'编辑订阅规则':'新建订阅规则'" width="720px"><form @submit.prevent="save"><section class="form-section"><h3>基本信息</h3><div class="form-row"><div class="form-field"><label>规则名称</label><input v-model="form.name" maxlength="100" required></div><label class="inline-check"><input v-model="form.enabled" type="checkbox">启用</label></div><div class="form-field"><label>规则描述</label><input v-model="form.description"></div></section><section class="form-section"><h3>收件人</h3><span v-for="email in recipients.split(/[,;\s，；]+/).filter(Boolean)" :key="email" class="email-tag">{{email}}</span><input v-model="recipients" placeholder="多个邮箱用逗号或空格分隔" required></section><section class="form-section"><h3>告警类型</h3><div class="mail-check-grid"><label v-for="(label,key) in labels" :key="key" class="mail-check-card" :class="{selected:form.alertTypes?.includes(key)}"><input type="checkbox" v-model="form.alertTypes" :value="key"><span>{{label}}</span></label></div></section><section class="form-section"><h3>关联任务</h3><div class="mail-check-grid"><label class="mail-check-card"><input type="radio" v-model="form.scope" value="all">全部任务</label><label class="mail-check-card"><input type="radio" v-model="form.scope" value="tasks">指定任务</label></div><div v-if="form.scope==='tasks'" class="mail-task-list"><label v-for="task in tasks" :key="task.id" class="inline-check"><input type="checkbox" v-model="form.taskIds" :value="task.id">{{task.name}} <span class="mono muted">#{{task.id}}</span></label></div></section><section class="form-section"><h3>触发频率</h3><div class="mail-check-grid"><label v-for="(label,key) in frequencies" :key="key" class="mail-check-card" :class="{selected:form.frequency===key}"><input type="radio" v-model="form.frequency" :value="key">{{label}}</label></div></section></form><template #footer><cdc-button @click="dialog=false">取消</cdc-button><cdc-button type="primary" :loading="busy" @click="save">保存规则</cdc-button></template></cdc-modal>
  </div>
</template>
